import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        a = int(next(iterator))
        b = int(next(iterator))
        s = []
        for _ in range(n):
            s.append(int(next(iterator)))
    except StopIteration:
        return

    dirty = s[:]
    intermediate = []
    dryer = []
    operations = []

    target = 1

    while target <= n:
        if intermediate and intermediate[-1] == target:
            count = 0
            while intermediate and intermediate[-1] == target + count:
                count += 1
                target += 1

            if count > b:
                print("NO")
                return

            operations.append((2, count))
            for _ in range(count):
                intermediate.pop()
                dryer.append(target - count + _)
        else:
            if not dirty:
                print("NO")
                return

            needed = 0
            found = False
            temp_target = target

            while needed < len(dirty) and not found:
                if dirty[needed] == temp_target:
                    found = True
                elif dirty[needed] > temp_target:
                    break
                needed += 1

            if not found:
                print("NO")
                return

            if needed > a:
                print("NO")
                return

            for i in range(needed):
                val = dirty.pop(0)
                intermediate.append(val)

            operations.append((1, needed))

    print("YES")
    print(len(operations))
    for t, c in operations:
        print(f"{t} {c}")

if __name__ == "__main__":
    solve()
